// Score technicians returned by PostgreSQL against the original request and AI analysis.
const webhookItem = $('Webhook').first().json;
const request = webhookItem.body || webhookItem;
const customerLat = Number(request.customer_lat);
const customerLon = Number(request.customer_lon);

if (!Number.isFinite(customerLat) || !Number.isFinite(customerLon)) {
  throw new Error('customer_lat and customer_lon must be valid numbers');
}

const aiResponse = $('OpenAI').first().json;
const rawContent = aiResponse.content
  ?? aiResponse.message?.content
  ?? aiResponse.choices?.[0]?.message?.content
  ?? '{}';

let aiAnalysis;
try {
  aiAnalysis = typeof rawContent === 'string' ? JSON.parse(rawContent) : rawContent;
} catch (error) {
  throw new Error('AI analysis is not valid JSON');
}

const normalizeList = (value) => {
  if (Array.isArray(value)) return value.map((item) => String(item).trim().toLowerCase());
  if (typeof value === 'string') {
    return value.replace(/[{}]/g, '').split(',').map((item) => item.trim().replace(/^"|"$/g, '').toLowerCase()).filter(Boolean);
  }
  return [];
};

const technicians = $input.all().map(({ json }) => ({
  id: String(json.id ?? ''),
  name: String(json.name ?? 'Technician'),
  lat: Number(json.lat),
  lon: Number(json.lon),
  skills: normalizeList(json.skills),
  currentLoad: Math.max(0, Number(json.current_load) || 0),
  inventory: normalizeList(json.van_inventory),
})).filter((tech) => tech.id && Number.isFinite(tech.lat) && Number.isFinite(tech.lon));

const requiredSkill = String(aiAnalysis.device_type ?? '').trim().toLowerCase();
const requiredParts = normalizeList(aiAnalysis.required_parts);

function distanceKm(lat1, lon1, lat2, lon2) {
  const radius = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2
    + Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.sin(dLon / 2) ** 2;
  return radius * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

const candidates = technicians
  .filter((tech) => tech.skills.includes(requiredSkill))
  .map((tech) => {
    const distance = distanceKm(customerLat, customerLon, tech.lat, tech.lon);
    const proximityScore = Math.max(0, 100 - distance * 5);
    const partsAvailable = requiredParts.every((part) => tech.inventory.includes(part));
    const partsScore = partsAvailable ? 100 : 0;
    const loadScore = Math.max(0, 100 - tech.currentLoad * 15);
    const score = proximityScore * 0.4 + partsScore * 0.4 + loadScore * 0.2;
    return { ...tech, distanceKm: Number(distance.toFixed(2)), partsAvailable, score: Number(score.toFixed(2)) };
  })
  .sort((a, b) => b.score - a.score || a.distanceKm - b.distanceKm || a.id.localeCompare(b.id));

const bestTech = candidates[0] || null;
const basePrice = aiAnalysis.urgency === 'critical' ? 150 : 100;
const travelFee = bestTech ? bestTech.distanceKm * 1.5 : 0;
const partsFee = requiredParts.length * 25;

return [{ json: {
  request_id: request.request_id || null,
  customer_name: request.customer_name || null,
  customer_address: request.customer_address || null,
  ai_analysis: aiAnalysis,
  assigned_technician: bestTech,
  final_price_usd: Number((basePrice + travelFee + partsFee).toFixed(2)),
  parts_available: bestTech?.partsAvailable === true,
  dispatch_status: bestTech?.partsAvailable === true ? 'AUTO_DISPATCH_READY' : 'MANUAL_REVIEW_REQUIRED',
  candidate_count: candidates.length,
} }];

